def test_expl_warnings_auto_shown() -> None:
    warnings = auto_explain_warnings(importance_spread=True, on_sample=True, surrogate_fidelity=0.6)
    assert any("correlated features" in warning for warning in warnings)
    assert any("random sample" in warning for warning in warnings)
    assert any("fidelity" in warning for warning in warnings)
    assert auto_explain_warnings() == ()


def test_shap_background_job_and_cache() -> None:
    assert shap_runs_in_job() is True
    key = explain_cache_key("hash-a", "random_forest", {"n_estimators": 100})
    same = explain_cache_key("hash-a", "random_forest", {"n_estimators": 100})
    different = explain_cache_key("hash-b", "random_forest", {"n_estimators": 100})
    assert key == same and len(key) == 32
    assert key != different
